j:jelly.script:
//
// show link if populated, hide if not 
//
function onChange_cmdb_ci_bsm(element, original, changed, loading) {
  var visibility = 'hidden';
   if (changed.length > 0)
    visibility = 'visible';

  var e = gel('${jvar_n}');
  e.style.visibility = visibility;
}

// show map if the sys_id is populated
function showMap(name) {
  var fieldName = name.split(':')[1];
  var n = gel(fieldName); 
  n = n.value; 
  if (n.length == 0) 
    alert("Populate CI field first"); 
  else
    showBSMMap(n); 
}

// show bsm map version for sys_id
function showBSMMap(sys_id) {
  var version = gel('bsm_chart.version').value;
  var url = '$keylines_bsm_map.do?sysparm_nameofstack=bsm'; 
  url += '&amp;';
  url += 'sysparm_attributes=table=cmdb_ci';
  url += ',id=' + sys_id;
  url += ',version=' + version; 
  url += ',ciview=,restack=true';
  g_navigation.open(url, 'super_bsm_map');
}

// register a handler for the cmdb_ci field
var h = new GlideEventHandler('onChange_cmdb_ci_bsm', onChange_cmdb_ci_bsm, '${ref}');
g_event_handlers.push(h);
